/* 4-way AVX2 SHA-256 (interleaved), public-domain style implementation.
   Processes 4 independent 64-byte blocks at a time, one round-state each.
   For a single message we stripe 4 streams of consecutive blocks? No —
   SHA-256 is serial. This file instead implements a single-stream SHA-256
   using AVX2 for the message schedule (the classic "sha256 with avx2
   message expansion") which is a modest win, PLUS a 4-lane version we can
   use if we ever hash independent blocks.

   Primary export for the benchmark: sha256_single().
*/
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/sha.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32-n)); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

static void sha256_compress(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        uint32_t v;
        memcpy(&v, block + i*4, 4);
        w[i] = bswap32(v);
    }
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
        uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

void sha256_single(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    size_t off = 0;
    while (off + 64 <= len) {
        sha256_compress(state, data + off);
        off += 64;
    }
    uint8_t block[64];
    size_t rem = len - off;
    memset(block, 0, 64);
    memcpy(block, data + off, rem);
    block[rem] = 0x80;
    if (rem >= 56) {
        sha256_compress(state, block);
        memset(block, 0, 64);
    }
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) block[63-i] = (uint8_t)(bits >> (8*i));
    sha256_compress(state, block);
    for (int i = 0; i < 8; i++) {
        uint32_t v = bswap32(state[i]);
        memcpy(out + i*4, &v, 4);
    }
}

/* ---------- 4-lane AVX2 message schedule + scalar rounds is not the goal.
   4 independent streams, each doing scalar compress, is just threading.
   Instead: AVX2 4-way interleaved compress of 4 independent blocks. */

static inline __m128i load_be(const uint8_t *p) {
    return _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)p),
        _mm_setr_epi8(3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12));
}

/* Process 4 independent 64-byte blocks, states are 8 x __m128i (4 lanes). */
static void sha256_compress4(__m128i st[8], const uint8_t *b0, const uint8_t *b1, const uint8_t *b2, const uint8_t *b3) {
    __m128i w[64];
    for (int i = 0; i < 16; i += 4) {
        __m128i r0 = load_be(b0 + i*4);
        __m128i r1 = load_be(b1 + i*4);
        __m128i r2 = load_be(b2 + i*4);
        __m128i r3 = load_be(b3 + i*4);
        /* transpose 4x4 */
        __m128i t0 = _mm_unpacklo_epi32(r0, r1);
        __m128i t1 = _mm_unpackhi_epi32(r0, r1);
        __m128i t2 = _mm_unpacklo_epi32(r2, r3);
        __m128i t3 = _mm_unpackhi_epi32(r2, r3);
        w[i+0] = _mm_unpacklo_epi64(t0, t2);
        w[i+1] = _mm_unpackhi_epi64(t0, t2);
        w[i+2] = _mm_unpacklo_epi64(t1, t3);
        w[i+3] = _mm_unpackhi_epi64(t1, t3);
    }
    for (int i = 16; i < 64; i++) {
        __m128i w15 = w[i-15];
        __m128i s0 = _mm_xor_si128(_mm_xor_si128(_mm_or_si128(_mm_srli_epi32(w15,7), _mm_slli_epi32(w15,25)),
                                                 _mm_or_si128(_mm_srli_epi32(w15,18), _mm_slli_epi32(w15,14))),
                                   _mm_srli_epi32(w15, 3));
        __m128i w2 = w[i-2];
        __m128i s1 = _mm_xor_si128(_mm_xor_si128(_mm_or_si128(_mm_srli_epi32(w2,17), _mm_slli_epi32(w2,15)),
                                                 _mm_or_si128(_mm_srli_epi32(w2,19), _mm_slli_epi32(w2,13))),
                                   _mm_srli_epi32(w2, 10));
        w[i] = _mm_add_epi32(_mm_add_epi32(w[i-16], s0), _mm_add_epi32(w[i-7], s1));
    }
    __m128i a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for (int i = 0; i < 64; i++) {
        __m128i S1 = _mm_xor_si128(_mm_xor_si128(_mm_or_si128(_mm_srli_epi32(e,6), _mm_slli_epi32(e,26)),
                                                 _mm_or_si128(_mm_srli_epi32(e,11), _mm_slli_epi32(e,21))),
                                   _mm_or_si128(_mm_srli_epi32(e,25), _mm_slli_epi32(e,7)));
        __m128i ch = _mm_xor_si128(_mm_and_si128(e, f), _mm_andnot_si128(e, g));
        __m128i t1 = _mm_add_epi32(_mm_add_epi32(h, S1), _mm_add_epi32(ch, _mm_add_epi32(_mm_set1_epi32(K[i]), w[i])));
        __m128i S0 = _mm_xor_si128(_mm_xor_si128(_mm_or_si128(_mm_srli_epi32(a,2), _mm_slli_epi32(a,30)),
                                                 _mm_or_si128(_mm_srli_epi32(a,13), _mm_slli_epi32(a,19))),
                                   _mm_or_si128(_mm_srli_epi32(a,22), _mm_slli_epi32(a,10)));
        __m128i maj = _mm_xor_si128(_mm_xor_si128(_mm_and_si128(a, b), _mm_and_si128(a, c)), _mm_and_si128(b, c));
        __m128i t2 = _mm_add_epi32(S0, maj);
        h=g; g=f; f=e; e=_mm_add_epi32(d, t1); d=c; c=b; b=a; a=_mm_add_epi32(t1, t2);
    }
    st[0]=_mm_add_epi32(st[0],a); st[1]=_mm_add_epi32(st[1],b); st[2]=_mm_add_epi32(st[2],c); st[3]=_mm_add_epi32(st[3],d);
    st[4]=_mm_add_epi32(st[4],e); st[5]=_mm_add_epi32(st[5],f); st[6]=_mm_add_epi32(st[6],g); st[7]=_mm_add_epi32(st[7],h);
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 20480000;
    uint8_t *data = malloc(n);
    memset(data, 0xab, n);
    uint8_t out[32], ref[32];
    int iters = 4;

    double t0 = now();
    for (int i = 0; i < iters; i++) sha256_single(data, n, out);
    printf("scalar: %.4f\n", (now()-t0)/iters);

    t0 = now();
    for (int i = 0; i < iters; i++) SHA256(data, n, ref);
    printf("openssl: %.4f\n", (now()-t0)/iters);
    printf("match %d\n", memcmp(out, ref, 32)==0);

    /* 4-lane over the whole buffer as 4 independent quarter-hashes, just for throughput */
    size_t q = (n/4/64)*64;
    __m128i st[8];
    uint32_t iv[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int k = 0; k < 8; k++) st[k] = _mm_set1_epi32(iv[k]);
        const uint8_t *p0 = data;
        const uint8_t *p1 = data + q;
        const uint8_t *p2 = data + 2*q;
        const uint8_t *p3 = data + 3*q;
        for (size_t i = 0; i < q; i += 64) {
            sha256_compress4(st, p0+i, p1+i, p2+i, p3+i);
        }
    }
    printf("avx2 4-lane (4 independent streams, no padding): %.4f\n", (now()-t0)/iters);
    return 0;
}
EOF
