#define ROTR(x,n) _mm_or_si128(_mm_srli_epi32((x),(n)), _mm_slli_epi32((x),32-(n)))

static inline __m128i load_be4(const uint8_t *p) {
    return _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)p),
        _mm_setr_epi8(3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12));
}

/* Fully unrolled 4-lane compress. w schedule computed on the fly in registers
   with a circular buffer of 16. */
static void sha256_compress4(__m128i st[8], const uint8_t *b0, const uint8_t *b1,
                             const uint8_t *b2, const uint8_t *b3) {
    __m128i w[16];
