#define ROTR8(x,n) _mm256_or_si256(_mm256_srli_epi32((x),(n)), _mm256_slli_epi32((x),32-(n)))

static void sha256_compress8(__m256i st[8], const uint8_t *blk[8]) {
    __m256i w[16];
