        for (int j = 0; j < 4; j++) {
            /* gather word j from each lane: extract scalar-ish via shuffle */
        }
        /* simpler: build each w word by inserting 8 lanes — slow path for setup only (16 words).
           Use scalar extract. Setup is small vs 64 rounds. */
        uint32_t tmp[8];
