        __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(ROTR8(e,6), ROTR8(e,11)), ROTR8(e,25)); \
        __m256i ch = _mm256_xor_si256(_mm256_and_si256(e,f), _mm256_andnot_si256(e,g)); \
        __m256i t1 = _mm256_add_epi32(h, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(K[i]), wi)))); \
        __m256i S0 = _mm256_xor_si256(_mm256_xor_si256(ROTR8(a,2), ROTR8(a,13)), ROTR8(a,22)); \
        __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(a,b), _mm256_and_si256(a,c)), _mm256_and_si256(b,c)); \
