static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 20480000;
    /* align n down later */
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    uint8_t ref[32];
    int iters = 4;
    double t0 = now();
    for (int i = 0; i < iters; i++) SHA256(data, n, ref);
    printf("openssl: %.4f\n", (now()-t0)/iters);

    size_t q = (n/4/64)*64;
    __m128i st[8];
    uint32_t iv[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int k = 0; k < 8; k++) st[k] = _mm_set1_epi32(iv[k]);
        const uint8_t *p0=data, *p1=data+q, *p2=data+2*q, *p3=data+3*q;
        for (size_t i = 0; i < q; i += 64)
            sha256_compress4(st, p0+i, p1+i, p2+i, p3+i);
    }
    printf("avx2-4 unrolled: %.4f  (hashed %.2f MB)\n", (now()-t0)/iters, (4.0*q*iters)/iters/1e6);

    size_t q8 = (n/8/64)*64;
    __m256i st8[8];
    const uint8_t *blks[8];
    t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int k = 0; k < 8; k++) st8[k] = _mm256_set1_epi32(iv[k]);
        for (int l = 0; l < 8; l++) blks[l] = data + l*q8;
        for (size_t i = 0; i < q8; i += 64) {
            const uint8_t *b[8];
            for (int l = 0; l < 8; l++) b[l] = blks[l] + i;
            sha256_compress8(st8, b);
        }
    }
    printf("avx2-8: %.4f  (hashed %.2f MB)\n", (now()-t0)/iters, (8.0*q8)/1e6);
    return 0;
}
