    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32-n)); }

__attribute__((noinline))
static void compress(uint32_t st[8], const uint8_t block[64]) {
    uint32_t w[64];
    const __m128i shuf = _mm_setr_epi8(3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12);
    for (int i = 0; i < 16; i += 4) {
        __m128i v = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block + i*4)), shuf);
        _mm_storeu_si128((__m128i*)(w + i), v);
    }
    for (int i = 16; i < 64; i++) {
        uint32_t x = w[i-15];
        uint32_t s0 = rotr(x,7) ^ rotr(x,18) ^ (x >> 3);
        uint32_t y = w[i-2];
        uint32_t s1 = rotr(y,17) ^ rotr(y,19) ^ (y >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    #pragma unroll
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    size_t n = 20480000;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0xab, n);
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    int iters = 4;
    double t0 = now();
    volatile uint32_t sink = 0;
    for (int it = 0; it < iters; it++) {
        uint32_t s[8]; memcpy(s, st, 32);
        for (size_t i = 0; i < n; i += 64) compress(s, data+i);
        sink += s[0];
    }
    printf("native scalar: %.4f sink %u\n", (now()-t0)/iters, sink);
    uint8_t out[32];
    t0 = now();
    for (int it = 0; it < iters; it++) SHA256(data, n, out);
    printf("openssl: %.4f\n", (now()-t0)/iters);
    return 0;
}
