void block_avx2(uint32_t dig[8], const uint8_t *p, size_t n);

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

static void sha256_avx2(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t dig[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    size_t nblocks = len / 64;
    size_t full = nblocks * 64;
    if (nblocks) block_avx2(dig, data, full);
    /* padding */
    uint8_t block[128];
    size_t rem = len - full;
    memset(block, 0, 128);
    memcpy(block, data + full, rem);
    block[rem] = 0x80;
    size_t pad_blocks = (rem >= 56) ? 2 : 1;
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) block[pad_blocks*64 - 1 - i] = (uint8_t)(bits >> (8*i));
    block_avx2(dig, block, pad_blocks*64);
    for (int i = 0; i < 8; i++) {
        uint32_t v = dig[i];
        out[i*4+0] = (uint8_t)(v >> 24);
        out[i*4+1] = (uint8_t)(v >> 16);
        out[i*4+2] = (uint8_t)(v >> 8);
        out[i*4+3] = (uint8_t)(v);
    }
}

