#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <openssl/sha.h>
void block_avx2(uint32_t dig[8], const uint8_t *p, size_t n);

static void dump32(const char *t, const uint8_t *p){ printf("%s ", t); for(int i=0;i<32;i++) printf("%02x", p[i]); printf("\n"); }

static int test(size_t n) {
    uint8_t *d = malloc(n + 256);
    for (size_t i = 0; i < n; i++) d[i] = (uint8_t)(i*17+3);
    uint32_t dig[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nb = n/64;
    if (nb) block_avx2(dig, d, nb*64);
    uint8_t mine[32];
    for (int i=0;i<8;i++){ uint32_t v=dig[i]; mine[i*4]=v>>24; mine[i*4+1]=v>>16; mine[i*4+2]=v>>8; mine[i*4+3]=v; }
    /* reference of exactly nb*64 bytes (no padding) via openssl of full message is different.
       Instead compute expected by hashing nb*64 bytes with our own known-good? Use openssl SHA256 of the
       raw blocks is NOT equal to the intermediate state. Compare only full padded hash. */
    free(d);
    printf("state-only nblocks=%zu first word %08x\n", nb, dig[0]);
    return 0;
}

/* full hash using block_avx2 for all blocks including padding */
static void sha256_avx2(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t dig[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len / 64;
    if (nblocks) block_avx2(dig, data, nblocks*64);
    uint8_t block[128];
    size_t rem = len - nblocks*64;
    memset(block, 0, 128);
    if (rem) memcpy(block, data + nblocks*64, rem);
    block[rem] = 0x80;
    size_t pad_blocks = (rem >= 56) ? 2 : 1;
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) block[pad_blocks*64 - 1 - i] = (uint8_t)(bits >> (8*i));
    block_avx2(dig, block, pad_blocks*64);
    for (int i = 0; i < 8; i++) {
        uint32_t v = dig[i];
        out[i*4]=v>>24; out[i*4+1]=v>>16; out[i*4+2]=v>>8; out[i*4+3]=v;
    }
}

int main() {
    size_t sizes[] = {0,1,3,55,56,63,64,65,100,127,128,129,191,192,193,200,1000,4096,100000,1000000,20480000};
    for (int i = 0; i < (int)(sizeof sizes/sizeof *sizes); i++) {
        size_t n = sizes[i];
        uint8_t *d = malloc(n+1);
        for (size_t j = 0; j < n; j++) d[j] = (uint8_t)(j*17+3);
        uint8_t a[32], b[32];
        sha256_avx2(d, n, a);
        SHA256(d, n, b);
        int ok = memcmp(a,b,32)==0;
        printf("n=%zu %s\n", n, ok?"OK":"MISMATCH");
        if (!ok) { dump32("mine", a); dump32("ref ", b); return 1; }
        free(d);
    }
    return 0;
}
EOF
